unverified.claim:
The fix-applier carry assertion got weaker. It used to check `The ticket:

${carried}
` and now checks only `

${carried}
`, so it no longer pins where in the brief the ticket lands (right after the new 'not a placeholder of this brief' sentence). The new sentence's placement is pinned only by the golden fixtures, and those come from the no-ledger fallback path.

unverified.suggested_fix:
Assert `spelling, not a placeholder of this brief:

${carried}
` so the sentence and the ticket stay adjacent.

const checked = [...required.map((a) => [a.placeholder, template.free.has(a.flag)]), ...(carriesTicket ? [[template.ticket, true]] : [])];
for (const [p, free] of checked) {
  const value = values.get(p);
  if (free) {
    if (value.trim() === `<${p}>`) die(`the rendered brief still carries <${p}> — its value is the unfilled placeholder`);
    continue;
  }
  for (const [q] of checked) if (value.includes(`<${q}>`)) die(`the rendered brief still carries <${q}> — an argument value spells it`);
}
